package com.visana.erp.network.foundation.infrastructure.web;
import com.visana.erp.core.infrastructure.config.security.KeycloakAuthenticatedPrincipalAdapter; import com.visana.erp.network.foundation.application.NetworkFoundationService; import com.visana.erp.platform.application.identity.*; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import io.swagger.v3.oas.annotations.tags.Tag;
@RestController @RequestMapping("/api/v1/network") @Tag(name="Network",description="Authenticated, minimum-data Plan 3 network queries") public class NetworkQueryController { private final NetworkFoundationService network; private final KeycloakAuthenticatedPrincipalAdapter principals; private final ActorResolverPort actors; public NetworkQueryController(NetworkFoundationService n,KeycloakAuthenticatedPrincipalAdapter p,ActorResolverPort a){network=n;principals=p;actors=a;} @GetMapping("/me") public MemberResponse me(@AuthenticationPrincipal Jwt jwt){return new MemberResponse(member(jwt));} @GetMapping("/direct") public List<MemberResponse> direct(@RequestParam(defaultValue="50") int limit,@AuthenticationPrincipal Jwt jwt){return network.direct(member(jwt),limit).stream().map(MemberResponse::new).toList();} @GetMapping("/ancestors") public List<MemberDepthResponse> ancestors(@RequestParam(defaultValue="50") int limit,@AuthenticationPrincipal Jwt jwt){return network.ancestors(member(jwt),limit).stream().map(x->new MemberDepthResponse(x.memberId(),x.depth())).toList();} @GetMapping("/descendants") public List<MemberDepthResponse> descendants(@RequestParam(defaultValue="50") int limit,@AuthenticationPrincipal Jwt jwt){return network.descendants(member(jwt),limit).stream().map(x->new MemberDepthResponse(x.memberId(),x.depth())).toList();} private UUID member(Jwt jwt){ActorResolution r=actors.resolve(principals.from(jwt,Set.of()));if(!r.isLinked())throw new UnlinkedIdentityException();return network.memberForActor(r.actorId().value());} public record MemberResponse(UUID memberId){} public record MemberDepthResponse(UUID memberId,int depth){} }
